insert into vocabulary (id, word, ipa, part_of_speech, translation_pt, example_en, example_pt, cefr_level, tags) values
('30000000-0000-0000-0000-000000001981', 'compromise', '/ˈkɑːmprəmaɪz/', 'verb', 'chegar a um meio-termo', 'Both sides had to compromise to reach a deal.', 'Os dois lados tiveram que ceder para fechar um acordo.', 'B2', array['business']),
('30000000-0000-0000-0000-000000001982', 'concession', '/kənˈseʃən/', 'noun', 'concessão', 'The company made a concession on the delivery date.', 'A empresa fez uma concessão quanto à data de entrega.', 'B2', array['business']),
('30000000-0000-0000-0000-000000001983', 'leverage', '/ˈlevərɪdʒ/', 'noun', 'poder de barganha', 'Having another offer gave her more leverage in the negotiation.', 'Ter outra oferta deu a ela mais poder de barganha na negociação.', 'B2', array['business']),
('30000000-0000-0000-0000-000000001984', 'counteroffer', '/ˈkaʊntərˌɔːfər/', 'noun', 'contraproposta', 'They rejected the price and made a counteroffer.', 'Eles rejeitaram o preço e fizeram uma contraproposta.', 'B2', array['business']),
('30000000-0000-0000-0000-000000001985', 'proposal', '/prəˈpoʊzəl/', 'noun', 'proposta', 'The client accepted our proposal without changes.', 'O cliente aceitou nossa proposta sem alterações.', 'B2', array['business']),
('30000000-0000-0000-0000-000000001986', 'terms', '/tɜːrmz/', 'noun', 'termos/condições', 'They agreed to the terms of the contract.', 'Eles concordaram com os termos do contrato.', 'B2', array['business']),
('30000000-0000-0000-0000-000000001987', 'deadlock', '/ˈdedlɑːk/', 'noun', 'impasse', 'The talks reached a deadlock over pricing.', 'As negociações chegaram a um impasse por causa do preço.', 'B2', array['business']),
('30000000-0000-0000-0000-000000001988', 'bottom line', '/ˈbɑːtəm laɪn/', 'noun', 'limite mínimo', 'Our bottom line is a ten percent discount, no more.', 'Nosso limite mínimo é um desconto de dez por cento, nada mais.', 'B2', array['business']),
('30000000-0000-0000-0000-000000001989', 'win-win', '/wɪn wɪn/', 'adjective', 'ganha-ganha', 'They found a win-win solution for both companies.', 'Eles encontraram uma solução ganha-ganha para as duas empresas.', 'B2', array['business']),
('30000000-0000-0000-0000-000000001990', 'trade-off', '/ˈtreɪd ɔːf/', 'noun', 'contrapartida', 'Lower prices often mean a trade-off in quality.', 'Preços mais baixos geralmente significam uma contrapartida na qualidade.', 'B2', array['business']),
('30000000-0000-0000-0000-000000001991', 'bargain', '/ˈbɑːrɡɪn/', 'verb', 'negociar/barganhar', 'They bargained for a better price at the market.', 'Eles negociaram um preço melhor no mercado.', 'B2', array['business']),
('30000000-0000-0000-0000-000000001992', 'stance', '/stæns/', 'noun', 'posição/postura', 'The union softened its stance after the meeting.', 'O sindicato suavizou sua posição depois da reunião.', 'B2', array['business']),
('30000000-0000-0000-0000-000000001993', 'flexible', '/ˈfleksəbəl/', 'adjective', 'flexível', 'We can be flexible about the delivery schedule.', 'Podemos ser flexíveis quanto ao cronograma de entrega.', 'B2', array['business']),
('30000000-0000-0000-0000-000000001994', 'firm', '/fɜːrm/', 'adjective', 'firme/inflexível', 'The seller remained firm on the price.', 'O vendedor permaneceu firme no preço.', 'B2', array['business']),
('30000000-0000-0000-0000-000000001995', 'mutual', '/ˈmjuːtʃuəl/', 'adjective', 'mútuo', 'They reached a mutual understanding after long talks.', 'Eles chegaram a um entendimento mútuo depois de longas conversas.', 'B2', array['business']),
('30000000-0000-0000-0000-000000001996', 'incentive', '/ɪnˈsentɪv/', 'noun', 'incentivo', 'The company offered an incentive to close the deal quickly.', 'A empresa ofereceu um incentivo para fechar o negócio rapidamente.', 'B2', array['business']),
('30000000-0000-0000-0000-000000001997', 'deal breaker', '/diːl ˈbreɪkər/', 'noun', 'ponto inegociável', 'The delivery date was a deal breaker for the client.', 'A data de entrega era um ponto inegociável para o cliente.', 'B2', array['business']),
('30000000-0000-0000-0000-000000001998', 'common ground', '/ˈkɑːmən ɡraʊnd/', 'noun', 'ponto em comum', 'It took time, but they finally found common ground.', 'Levou tempo, mas eles finalmente encontraram um ponto em comum.', 'B2', array['business']),
('30000000-0000-0000-0000-000000001999', 'persuasive', '/pərˈsweɪsɪv/', 'adjective', 'persuasivo', 'Her persuasive argument convinced the board.', 'O argumento persuasivo dela convenceu o conselho.', 'B2', array['business']),
('30000000-0000-0000-0000-000000002000', 'compelling', '/kəmˈpelɪŋ/', 'adjective', 'convincente', 'He gave a compelling reason to lower the price.', 'Ele deu um motivo convincente para baixar o preço.', 'B2', array['business']),
('30000000-0000-0000-0000-000000002001', 'rapport', '/ræˈpɔːr/', 'noun', 'empatia/conexão', 'Building rapport with the client made the negotiation easier.', 'Criar empatia com o cliente facilitou a negociação.', 'B2', array['business']),
('30000000-0000-0000-0000-000000002002', 'objection', '/əbˈdʒekʃən/', 'noun', 'objeção', 'The lawyer raised an objection to the new clause.', 'O advogado levantou uma objeção à nova cláusula.', 'B2', array['business']),
('30000000-0000-0000-0000-000000002003', 'clarify', '/ˈklærəfaɪ/', 'verb', 'esclarecer', 'Could you clarify the payment terms before we sign?', 'Você poderia esclarecer as condições de pagamento antes de assinarmos?', 'B2', array['business']),
('30000000-0000-0000-0000-000000002004', 'reconsider', '/ˌriːkənˈsɪdər/', 'verb', 'reconsiderar', 'They asked us to reconsider our offer.', 'Eles nos pediram para reconsiderar nossa oferta.', 'B2', array['business']),
('30000000-0000-0000-0000-000000002005', 'finalize', '/ˈfaɪnəlaɪz/', 'verb', 'finalizar', 'We hope to finalize the agreement by Friday.', 'Esperamos finalizar o acordo até sexta-feira.', 'B2', array['business']),
('30000000-0000-0000-0000-000000002006', 'draft', '/dræft/', 'verb', 'redigir', 'The lawyers drafted a new version of the contract.', 'Os advogados redigiram uma nova versão do contrato.', 'B2', array['business']),
('30000000-0000-0000-0000-000000002007', 'binding', '/ˈbaɪndɪŋ/', 'adjective', 'vinculante', 'The agreement becomes binding once both parties sign.', 'O acordo se torna vinculante assim que as duas partes assinam.', 'B2', array['business']),
('30000000-0000-0000-0000-000000002008', 'non-negotiable', '/nɑːn nɪˈɡoʊʃiəbəl/', 'adjective', 'não negociável', 'The safety requirements are non-negotiable.', 'Os requisitos de segurança não são negociáveis.', 'B2', array['business']),
('30000000-0000-0000-0000-000000002009', 'escalate', '/ˈeskəleɪt/', 'verb', 'escalar', 'If we cannot agree, we will escalate the issue to management.', 'Se não conseguirmos concordar, vamos escalar a questão para a gerência.', 'B2', array['business']),
('30000000-0000-0000-0000-000000002010', 'settle', '/ˈsetəl/', 'verb', 'chegar a um acordo', 'The two companies decided to settle out of court.', 'As duas empresas decidiram chegar a um acordo fora do tribunal.', 'B2', array['business']);

