('20000000-0000-0000-0000-000000000331', 'multiple_choice', 4, '{"question": "Both sides had to ___ to reach a deal.", "audio_text": null, "options": ["compromise", "escalate", "clarify"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000331', 'multiple_choice', 5, '{"question": "They rejected the price and made a ___.", "audio_text": null, "options": ["counteroffer", "concession", "deadlock"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000331', 'matching', 6, '{"pairs": [{"left": "compromise", "right": "chegar a um meio-termo"}, {"left": "concession", "right": "concessão"}, {"left": "leverage", "right": "poder de barganha"}, {"left": "counteroffer", "right": "contraproposta"}, {"left": "proposal", "right": "proposta"}, {"left": "terms", "right": "termos/condições"}]}'),
('20000000-0000-0000-0000-000000000331', 'fill_blank', 7, '{"sentence": "The client accepted our ___ without changes.", "options": ["proposal", "leverage", "concession"], "correct": "proposal", "translation": "O cliente aceitou nossa proposta sem alterações."}'),
('20000000-0000-0000-0000-000000000331', 'fill_blank', 8, '{"sentence": "They agreed to the ___ of the contract.", "options": ["terms", "leverage", "counteroffer"], "correct": "terms", "translation": "Eles concordaram com os termos do contrato."}'),
('20000000-0000-0000-0000-000000000331', 'word_order', 9, '{"words": ["The", "company", "made", "a", "concession", "on", "the", "delivery", "date"], "correct_sentence": "The company made a concession on the delivery date", "translation": "A empresa fez uma concessão quanto à data de entrega"}'),
('20000000-0000-0000-0000-000000000331', 'word_order', 10, '{"words": ["Having", "another", "offer", "gave", "her", "more", "leverage", "in", "the", "negotiation"], "correct_sentence": "Having another offer gave her more leverage in the negotiation", "translation": "Ter outra oferta deu a ela mais poder de barganha na negociação"}'),
('20000000-0000-0000-0000-000000000331', 'reading', 11, '{"passage": "Every negotiation involves a proposal, and often a counteroffer follows. Skilled negotiators know when to compromise and when to hold their ground. A small concession on minor terms can sometimes give one side more leverage on the points that really matter.", "translation": "Toda negociação envolve uma proposta, e frequentemente uma contraproposta vem em seguida. Negociadores habilidosos sabem quando ceder e quando manter a posição. Uma pequena concessão em termos menores às vezes pode dar a um dos lados mais poder de barganha nos pontos que realmente importam.", "question": "What often follows a proposal, according to the text?", "options": ["A concession", "A counteroffer", "A deadlock"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000331', 'listening', 12, '{"audio_text": "Both sides had to compromise to reach a deal. They rejected the price and made a counteroffer. The client accepted our proposal without changes.", "question": "What did they do after rejecting the price, according to the audio?", "options": ["Made a counteroffer", "Accepted the terms", "Escalated the issue"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000331', 'dictation', 13, '{"audio_text": "Both sides had to compromise to reach a deal.", "expected": "Both sides had to compromise to reach a deal."}'),
('20000000-0000-0000-0000-000000000331', 'typing', 14, '{"prompt_pt": "Traduza: ''Fizemos uma contraproposta, mas eles não concordaram com os novos termos.''", "expected": "We made a counteroffer, but they did not agree to the new terms.", "ai_review": true}'),

-- Lição 332: Situações de negociação (deadlock, bottom line, win-win, trade-off, bargain, stance)
('20000000-0000-0000-0000-000000000332', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001987", "show_image": false}'),
