('20000000-0000-0000-0000-000000000332', 'multiple_choice', 4, '{"question": "The talks reached a ___ over pricing.", "audio_text": null, "options": ["deadlock", "trade-off", "bargain"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000332', 'multiple_choice', 5, '{"question": "They found a ___ solution for both companies.", "audio_text": null, "options": ["win-win", "firm", "flexible"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000332', 'matching', 6, '{"pairs": [{"left": "deadlock", "right": "impasse"}, {"left": "bottom line", "right": "limite mínimo"}, {"left": "win-win", "right": "ganha-ganha"}, {"left": "trade-off", "right": "contrapartida"}, {"left": "bargain", "right": "negociar/barganhar"}, {"left": "stance", "right": "posição/postura"}]}'),
('20000000-0000-0000-0000-000000000332', 'fill_blank', 7, '{"sentence": "Our ___ is a ten percent discount, no more.", "options": ["bottom line", "trade-off", "stance"], "correct": "bottom line", "translation": "Nosso limite mínimo é um desconto de dez por cento, nada mais."}'),
('20000000-0000-0000-0000-000000000332', 'fill_blank', 8, '{"sentence": "The union softened its ___ after the meeting.", "options": ["stance", "bottom line", "deadlock"], "correct": "stance", "translation": "O sindicato suavizou sua posição depois da reunião."}'),
('20000000-0000-0000-0000-000000000332', 'word_order', 9, '{"words": ["Lower", "prices", "often", "mean", "a", "trade-off", "in", "quality"], "correct_sentence": "Lower prices often mean a trade-off in quality", "translation": "Preços mais baixos geralmente significam uma contrapartida na qualidade"}'),
('20000000-0000-0000-0000-000000000332', 'word_order', 10, '{"words": ["They", "bargained", "for", "a", "better", "price", "at", "the", "market"], "correct_sentence": "They bargained for a better price at the market", "translation": "Eles negociaram um preço melhor no mercado"}'),
('20000000-0000-0000-0000-000000000332', 'reading', 11, '{"passage": "Negotiations do not always go smoothly. Sometimes talks reach a deadlock, and both sides must decide whether a trade-off is acceptable. Good negotiators know their bottom line before they bargain, and they are ready to adjust their stance if it leads to a win-win outcome.", "translation": "Negociações nem sempre andam bem. Às vezes as conversas chegam a um impasse, e os dois lados precisam decidir se uma contrapartida é aceitável. Bons negociadores sabem qual é seu limite mínimo antes de barganhar, e estão prontos para ajustar sua posição se isso levar a um resultado ganha-ganha.", "question": "What should good negotiators know before they bargain, according to the text?", "options": ["Their bottom line", "The other side''s stance", "The trade-off percentage"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000332', 'listening', 12, '{"audio_text": "The talks reached a deadlock over pricing. They found a win-win solution for both companies. The union softened its stance after the meeting.", "question": "What did the talks reach over pricing, according to the audio?", "options": ["A win-win solution", "A deadlock", "A concession"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000332', 'dictation', 13, '{"audio_text": "They found a win-win solution for both companies.", "expected": "They found a win-win solution for both companies."}'),
('20000000-0000-0000-0000-000000000332', 'typing', 14, '{"prompt_pt": "Traduza: ''As negociações chegaram a um impasse, mas ambos os lados ajustaram sua postura.''", "expected": "The negotiations reached a deadlock, but both sides adjusted their stance.", "ai_review": true}'),

