('20000000-0000-0000-0000-000000000333', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001993", "show_image": false}'),
('20000000-0000-0000-0000-000000000333', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000001994", "show_image": false}'),
('20000000-0000-0000-0000-000000000333', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000001998", "show_image": false}'),
('20000000-0000-0000-0000-000000000333', 'multiple_choice', 4, '{"question": "We can be ___ about the delivery schedule.", "audio_text": null, "options": ["flexible", "firm", "non-negotiable"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000333', 'multiple_choice', 5, '{"question": "The seller remained ___ on the price.", "audio_text": null, "options": ["firm", "flexible", "mutual"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000333', 'matching', 6, '{"pairs": [{"left": "flexible", "right": "flexível"}, {"left": "firm", "right": "firme/inflexível"}, {"left": "mutual", "right": "mútuo"}, {"left": "incentive", "right": "incentivo"}, {"left": "deal breaker", "right": "ponto inegociável"}, {"left": "common ground", "right": "ponto em comum"}]}'),
('20000000-0000-0000-0000-000000000333', 'fill_blank', 7, '{"sentence": "The delivery date was a ___ for the client.", "options": ["deal breaker", "concession", "incentive"], "correct": "deal breaker", "translation": "A data de entrega era um ponto inegociável para o cliente."}'),
('20000000-0000-0000-0000-000000000333', 'fill_blank', 8, '{"sentence": "It took time, but they finally found ___.", "options": ["common ground", "a deadlock", "a bottom line"], "correct": "common ground", "translation": "Levou tempo, mas eles finalmente encontraram um ponto em comum."}'),
('20000000-0000-0000-0000-000000000333', 'word_order', 9, '{"words": ["They", "reached", "a", "mutual", "understanding", "after", "long", "talks"], "correct_sentence": "They reached a mutual understanding after long talks", "translation": "Eles chegaram a um entendimento mútuo depois de longas conversas"}'),
('20000000-0000-0000-0000-000000000333', 'word_order', 10, '{"words": ["The", "company", "offered", "an", "incentive", "to", "close", "the", "deal", "quickly"], "correct_sentence": "The company offered an incentive to close the deal quickly", "translation": "A empresa ofereceu um incentivo para fechar o negócio rapidamente"}'),
('20000000-0000-0000-0000-000000000333', 'reading', 11, '{"passage": "Attitudes shape how a negotiation unfolds. Being flexible on small details can build trust, while staying firm on a real deal breaker protects your interests. Offering an incentive can help both parties reach mutual satisfaction, and searching for common ground often opens the door to an agreement.", "translation": "Atitudes moldam como uma negociação se desenrola. Ser flexível em pequenos detalhes pode construir confiança, enquanto permanecer firme em um verdadeiro ponto inegociável protege seus interesses. Oferecer um incentivo pode ajudar as duas partes a alcançarem satisfação mútua, e buscar um ponto em comum costuma abrir a porta para um acordo.", "question": "What can staying firm on a real deal breaker do, according to the text?", "options": ["Build trust", "Protect your interests", "Open the door to agreement"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000333', 'listening', 12, '{"audio_text": "We can be flexible about the delivery schedule. The seller remained firm on the price. They reached a mutual understanding after long talks.", "question": "What did the seller remain firm on, according to the audio?", "options": ["The schedule", "The price", "The terms"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000333', 'dictation', 13, '{"audio_text": "We can be flexible about the delivery schedule.", "expected": "We can be flexible about the delivery schedule."}'),
('20000000-0000-0000-0000-000000000333', 'typing', 14, '{"prompt_pt": "Traduza: ''Somos flexíveis quanto ao prazo, mas o preço é um ponto inegociável.''", "expected": "We are flexible about the deadline, but the price is a deal breaker.", "ai_review": true}'),

-- Lição 334: Persuasão (persuasive, compelling, rapport, objection, clarify, reconsider)
