('20000000-0000-0000-0000-000000000334', 'multiple_choice', 4, '{"question": "Her ___ argument convinced the board.", "audio_text": null, "options": ["persuasive", "firm", "binding"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000334', 'multiple_choice', 5, '{"question": "The lawyer raised an ___ to the new clause.", "audio_text": null, "options": ["objection", "incentive", "concession"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000334', 'matching', 6, '{"pairs": [{"left": "persuasive", "right": "persuasivo"}, {"left": "compelling", "right": "convincente"}, {"left": "rapport", "right": "empatia/conexão"}, {"left": "objection", "right": "objeção"}, {"left": "clarify", "right": "esclarecer"}, {"left": "reconsider", "right": "reconsiderar"}]}'),
('20000000-0000-0000-0000-000000000334', 'fill_blank', 7, '{"sentence": "He gave a ___ reason to lower the price.", "options": ["compelling", "non-negotiable", "binding"], "correct": "compelling", "translation": "Ele deu um motivo convincente para baixar o preço."}'),
('20000000-0000-0000-0000-000000000334', 'fill_blank', 8, '{"sentence": "They asked us to ___ our offer.", "options": ["reconsider", "clarify", "escalate"], "correct": "reconsider", "translation": "Eles nos pediram para reconsiderar nossa oferta."}'),
('20000000-0000-0000-0000-000000000334', 'word_order', 9, '{"words": ["Building", "rapport", "with", "the", "client", "made", "the", "negotiation", "easier"], "correct_sentence": "Building rapport with the client made the negotiation easier", "translation": "Criar empatia com o cliente facilitou a negociação"}'),
('20000000-0000-0000-0000-000000000334', 'word_order', 10, '{"words": ["Could", "you", "clarify", "the", "payment", "terms", "before", "we", "sign"], "correct_sentence": "Could you clarify the payment terms before we sign", "translation": "Você poderia esclarecer as condições de pagamento antes de assinarmos"}'),
('20000000-0000-0000-0000-000000000334', 'reading', 11, '{"passage": "Persuasion is a key skill in negotiation. A persuasive speaker uses compelling arguments and builds rapport with the other side. When someone raises an objection, it helps to clarify the point calmly instead of getting defensive, and sometimes it is worth asking the other party to reconsider their position.", "translation": "Persuasão é uma habilidade essencial na negociação. Um bom orador persuasivo usa argumentos convincentes e cria empatia com o outro lado. Quando alguém levanta uma objeção, ajuda esclarecer o ponto com calma em vez de ficar na defensiva, e às vezes vale a pena pedir para a outra parte reconsiderar sua posição.", "question": "What helps when someone raises an objection, according to the text?", "options": ["Getting defensive", "Clarifying the point calmly", "Ignoring it"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000334', 'listening', 12, '{"audio_text": "Her persuasive argument convinced the board. Building rapport with the client made the negotiation easier. They asked us to reconsider our offer.", "question": "What made the negotiation easier, according to the audio?", "options": ["A persuasive argument", "Building rapport with the client", "Reconsidering the offer"], "correct_index": 1}'),
